<template><q-page class="review-page"><header><p class="eyebrow">REVISÃO ADAPTATIVA</p><h1>Seu domínio</h1><p>Use as evidências reais de revisões e cadernos para escolher o próximo foco.</p></header><q-tabs v-model="tab" dense no-caps align="left" active-color="primary" indicator-color="primary"><q-tab name="session" label="Revisar cards"/><q-tab name="mastery" label="Mapa de domínio"/></q-tabs><ReviewSessionPage v-if="tab==='session'"/><template v-else><q-banner v-if="error" rounded class="error q-mb-md">{{ error }}</q-banner><q-card class="review-card"><q-card-section class="row items-center justify-between"><div><h2>Mapa de domínio</h2><p>Assuntos canônicos com evidência suficiente.</p></div><q-btn flat no-caps color="primary" label="Atualizar" :loading="loading" @click="loadMastery()"/></q-card-section><q-separator/><q-card-section v-if="loading"><q-skeleton v-for="index in 4" :key="index" type="text" class="q-my-sm"/></q-card-section><q-card-section v-else-if="!mastery.length" class="empty">Ainda não há evidências suficientes para formar seu mapa de domínio.</q-card-section><q-list v-else separator><q-item v-for="node in mastery" :key="node.conceptId"><q-item-section><q-item-label>{{ node.name }}</q-item-label><q-item-label caption>{{ node.confidence === 'INSUFFICIENT' ? 'Dados insuficientes' : node.evidenceCount + ' evidências' }}</q-item-label></q-item-section><q-item-section side><q-badge :color="node.masteryScore === null ? 'grey-6' : 'primary'">{{ node.masteryScore === null ? '—' : Math.round(node.masteryScore) + '%' }}</q-badge></q-item-section></q-item></q-list></q-card></template></q-page></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import ReviewSessionPage from './ReviewSessionPage.vue';import { useReview } from './useReview';const tab=ref('session');const { error, loadMastery, loading, mastery } = useReview();onMounted(() => { void loadMastery() });</script>
<style scoped>.review-page{max-width:980px;margin:auto;padding:40px 32px}.eyebrow{margin:0;color:#7187ad;font-weight:800;letter-spacing:.1em;font-size:11px}.review-page h1,.review-page h2{margin:6px 0;color:#142950}.review-page header>p:last-child,.review-card p{color:#71819e}.review-card{margin-top:24px;border-radius:20px}.empty{color:#71819e;padding:32px;text-align:center}.error{background:#fff3f2;color:#ae2f25}@media(max-width:599px){.review-page{padding:24px 16px}}</style>
